1	use std::io::{Read, Write};
2	use std::path::Path;
3	use std::process::Stdio;
4	use std::time::{Duration, Instant};
5	
6	use callisto_model::{
7	    known_credential_env_values, redact_command_stderr, redact_known_secrets, CommandError, CommandOutput,
8	    CommandRunner,
9	};
10	
11	/// The most recent subprocess that exited non-zero, as a redacted summary a failing release can print after its error.
12	static LAST_FAILED_COMMAND: std::sync::Mutex<Option<String>> = std::sync::Mutex::new(None);
13	
14	const FAILED_COMMAND_TAIL_LINES: usize = 20;
15	const FAILED_COMMAND_TAIL_BYTES: usize = 2048;
16	
17	/// `program`'s exit status and the redacted end of its stderr: at most 20 lines and 2 KiB.
18	fn failed_command_summary(program: &str, exit_code: Option<i32>, stderr: &str) -> String {
19	    let redacted = redact_command_stderr(stderr);
20	    let lines: Vec<&str> = redacted.lines().collect();
21	    let tail = lines[lines.len().saturating_sub(FAILED_COMMAND_TAIL_LINES)..].join("\n");
22	    let mut start = tail.len().saturating_sub(FAILED_COMMAND_TAIL_BYTES);
23	    while !tail.is_char_boundary(start) {
24	        start += 1;
25	    }
26	    let status = exit_code.map_or("was terminated".to_string(), |code| format!("exited with {code}"));
27	    format!("`{program}` {status}\n{}", &tail[start..])
28	}
29	
30	fn note_failed_command(program: &str, exit_code: Option<i32>, stderr: &str) {
31	    if exit_code == Some(0) {
32	        return;
33	    }
34	    if let Ok(mut last) = LAST_FAILED_COMMAND.lock() {
35	        *last = Some(failed_command_summary(program, exit_code, stderr));
36	    }
37	}
38	
39	/// The summary of the most recent failed subprocess, if any; printed after an indeterminate release error.
40	pub fn last_failed_command() -> Option<String> {
41	    LAST_FAILED_COMMAND.lock().ok().and_then(|last| last.clone())
42	}
43	
44	/// Caps how much of a subprocess's stdout/stderr this process will retain
45	/// in memory. The pipe is still drained in full past this point (bytes
46	/// beyond the cap are read and discarded, never accumulated) so a chatty
47	/// child can never deadlock waiting on a full OS pipe buffer -- this
48	/// bounds memory, not duration (`PUBLISH_TIMEOUT_SECS` bounds that
49	/// separately).
50	const MAX_CAPTURED_OUTPUT_BYTES: usize = 10 * 1024 * 1024;
51	
52	const RELEASE_CREDENTIALS: &[&str] = &[
53	    "CARGO_REGISTRY_TOKEN",
54	    "GH_TOKEN",
55	    "GITHUB_TOKEN",
56	    "NPM_CONFIG_TOKEN",
57	    "NPM_TOKEN",
58	    "NODE_AUTH_TOKEN",
59	    "PYPI_TOKEN",
60	    "CALLISTO_PUBLISH_NPM_CONFIG",
61	    "TWINE_USERNAME",
62	    "TWINE_PASSWORD",
63	];
64	
65	const ACTION_SECRET_INPUTS: &[&str] = &[
66	    "CARGO_REGISTRY_TOKEN",
67	    "GH_TOKEN",
68	    "GITHUB_TOKEN",
69	    "NPM_TOKEN",
70	    "PYPI_TOKEN",
71	    "CALLISTO_PUBLISH_NPM_CONFIG",
72	    "TWINE_USERNAME",
73	    "TWINE_PASSWORD",
74	];
75	
76	struct ChildEnvironment<'a> {
77	    remove: &'a [&'a str],
78	    set: &'a [(&'a str, &'a str)],
79	}
80	
81	/// The release credentials a tool reads from its own environment. Every other release
82	/// credential is removed from its child process, so a tool never sees a secret it does not use.
83	/// A tool absent here needs none; publishers receive theirs explicitly instead.
84	fn credentials_needed_by(tool: &str) -> &'static [&'static str] {
85	    match tool {
86	        "npm" | "pnpm" | "yarn" | "bun" => &["NPM_CONFIG_TOKEN", "NPM_TOKEN", "NODE_AUTH_TOKEN"],
87	        "cargo" => &["CARGO_REGISTRY_TOKEN"],
88	        // `gh` reads GH_TOKEN, and GITHUB_TOKEN when that is unset; it runs the attestation
89	        // check and every forge call, and refuses to run without a token.
90	        "gh" => &["GH_TOKEN", "GITHUB_TOKEN"],
91	        _ => &[],
92	    }
93	}
94	
95	fn unrelated_credentials(program: &str) -> Vec<&'static str> {
96	    let tool = Path::new(program)
97	        .file_name()
98	        .and_then(|name| name.to_str())
99	        .unwrap_or(program);
100	    let keep = credentials_needed_by(tool);
101	    RELEASE_CREDENTIALS
102	        .iter()
103	        .copied()
104	        .filter(|credential| !keep.contains(credential))
105	        .collect()
106	}
107	
108	fn remove_env(command: &mut std::process::Command, names: &[&str]) {
109	    for name in names {
110	        command.env_remove(name);
111	    }
112	}
113	
114	pub struct CliCommandRunner;
115	
116	impl CommandRunner for CliCommandRunner {
117	    fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
118	        let mut command = std::process::Command::new(program);
119	        command.args(args).current_dir(cwd);
120	        remove_env(&mut command, &unrelated_credentials(program));
121	        let output = command
122	            .stdin(Stdio::null())
123	            .stdout(Stdio::piped())
124	            .stderr(Stdio::piped())
125	            .output();
126	
127	        match output {
128	            Ok(o) => {
129	                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
130	                // Keep raw stderr available to callers for protocol/error
131	                // classification, but never leak credentials to the terminal.
132	                if !stderr.is_empty() {
133	                    let secrets = known_credential_env_values(std::env::vars());
134	                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
135	                }
136	                note_failed_command(program, o.status.code(), &stderr);
137	                Ok(CommandOutput {
138	                    exit_code: o.status.code(),
139	                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
140	                    stderr,
141	                })
142	            }
143	            Err(e) if e.kind() == std::io::ErrorKind::NotFound => Err(CommandError::NotFound {
144	                program: program.to_string(),
145	            }),
146	            Err(e) => Err(CommandError::Io {
147	                program: program.to_string(),
148	                message: e.to_string(),
149	            }),
150	        }
151	    }
152	
153	    fn run_with_timeout(
154	        &self,
155	        program: &str,
156	        args: &[&str],
157	        cwd: &Path,
158	        timeout: Duration,
159	    ) -> Result<CommandOutput, CommandError> {
160	        // `known_credential_env_values` is scanned here, at the trait-method
161	        // call site, rather than inside `run_with_timeout_impl` itself: this
162	        // keeps the impl fn pure and directly unit-testable with a synthetic
163	        // secrets list (no process-env mutation, which would race against
164	        // other tests running in parallel in this binary).
165	        let remove = unrelated_credentials(program);
166	        run_with_timeout_impl(
167	            program,
168	            args,
169	            cwd,
170	            timeout,
171	            LiveEcho::STDERR,
172	            known_credential_env_values(std::env::vars()),
173	            ChildEnvironment {
174	                remove: &remove,
175	                set: &[],
176	            },
177	        )
178	    }
179	
180	    fn run_with_timeout_env_filtered(
181	        &self,
182	        program: &str,
183	        args: &[&str],
184	        cwd: &Path,
185	        timeout: Duration,
186	        removed: &[&str],
187	    ) -> Result<CommandOutput, CommandError> {
188	        let remove = unrelated_credentials(program)
189	            .into_iter()
190	            .chain(removed.iter().copied())
191	            .collect::<Vec<_>>();
192	        run_with_timeout_impl(
193	            program,
194	            args,
195	            cwd,
196	            timeout,
197	            LiveEcho::STDERR,
198	            known_credential_env_values(std::env::vars()),
199	            ChildEnvironment {
200	                remove: &remove,
201	                set: &[],
202	            },
203	        )
204	    }
205	
206	    fn run_with_timeout_publisher(
207	        &self,
208	        program: &str,
209	        args: &[&str],
210	        cwd: &Path,
211	        timeout: Duration,
212	        env: &[(&str, &str)],
213	    ) -> Result<CommandOutput, CommandError> {
214	        let remove = unrelated_credentials(program)
215	            .into_iter()
216	            .chain(ACTION_SECRET_INPUTS.iter().copied())
217	            .collect::<Vec<_>>();
218	        run_with_timeout_impl(
219	            program,
220	            args,
221	            cwd,
222	            timeout,
223	            LiveEcho::BOTH,
224	            known_credential_env_values(std::env::vars()),
225	            ChildEnvironment {
226	                remove: &remove,
227	                set: env,
228	            },
229	        )
230	    }
231	
232	    fn run_quiet(
233	        &self,
234	        program: &str,
235	        args: &[&str],
236	        cwd: &Path,
237	        timeout: Duration,
238	    ) -> Result<CommandOutput, CommandError> {
239	        // Quiet mode never echoes stderr live (see `LiveEcho::NONE`
240	        // below), so there's nothing to redact -- pass an empty secrets
241	        // list rather than paying for an env scan that can only go unused.
242	        let remove = unrelated_credentials(program);
243	        run_with_timeout_impl(
244	            program,
245	            args,
246	            cwd,
247	            timeout,
248	            LiveEcho::NONE,
249	            Vec::new(),
250	            ChildEnvironment {
251	                remove: &remove,
252	                set: &[],
253	            },
254	        )
255	    }
256	
257	    fn run_with_stdin(
258	        &self,
259	        program: &str,
260	        args: &[&str],
261	        cwd: &Path,
262	        stdin: &[u8],
263	    ) -> Result<CommandOutput, CommandError> {
264	        let mut command = std::process::Command::new(program);
265	        command.args(args).current_dir(cwd);
266	        remove_env(&mut command, &unrelated_credentials(program));
267	        let mut child = command
268	            .stdin(Stdio::piped())
269	            .stdout(Stdio::piped())
270	            .stderr(Stdio::piped())
271	            .spawn()
272	            .map_err(|e| {
273	                if e.kind() == std::io::ErrorKind::NotFound {
274	                    CommandError::NotFound {
275	                        program: program.to_string(),
276	                    }
277	                } else {
278	                    CommandError::Io {
279	                        program: program.to_string(),
280	                        message: e.to_string(),
281	                    }
282	                }
283	            })?;
284	
285	        // Write the payload on its own thread, concurrently with this
286	        // thread draining stdout/stderr via `wait_with_output` below.
287	        // A protocol like `git cat-file --batch` replies to each stdin
288	        // line as it arrives, so writing everything up front on the same
289	        // thread that also has to read the reply back could deadlock once
290	        // either the stdin or the stdout pipe buffer fills -- exactly the
291	        // hazard `run_with_timeout_impl` above uses dedicated reader
292	        // threads to avoid, mirrored here for the write side.
293	        let mut stdin_pipe = child.stdin.take().expect("stdin was requested as piped");
294	        let payload = stdin.to_vec();
295	        let writer = std::thread::spawn(move || {
296	            // A closed read end (the child exited early, e.g. on a bad
297	            // invocation) would otherwise surface as a `BrokenPipe` write
298	            // error here; the child's actual exit code/stderr, captured by
299	            // `wait_with_output` below, is the caller-facing signal for
300	            // that failure, so a write error on this thread is dropped
301	            // rather than reported.
302	            drop(stdin_pipe.write_all(&payload));
303	            drop(stdin_pipe.flush());
304	        });
305	
306	        let output = child.wait_with_output();
307	        // The writer thread only writes then drops its handle, so it must
308	        // already be finished (or about to finish) by the time the child
309	        // has exited and `wait_with_output` has drained its output --
310	        // joining here can't block indefinitely.
311	        drop(writer.join());
312	
313	        match output {
314	            Ok(o) => {
315	                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
316	                if !stderr.is_empty() {
317	                    let secrets = known_credential_env_values(std::env::vars());
318	                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
319	                }
320	                note_failed_command(program, o.status.code(), &stderr);
321	                Ok(CommandOutput {
322	                    exit_code: o.status.code(),
323	                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
324	                    stderr,
325	                })
326	            }
327	            Err(e) => Err(CommandError::Io {
328	                program: program.to_string(),
329	                message: e.to_string(),
330	            }),
331	        }
332	    }
333	}
334	
335	/// Which of a subprocess's streams [`run_with_timeout_impl`] prints live, to this process's stderr, as lines arrive.
336	/// Captured `CommandOutput` is identical either way; this only affects what the terminal shows while it runs.
337	#[derive(Clone, Copy, PartialEq, Eq)]
338	struct LiveEcho {
339	    stdout: bool,
340	    stderr: bool,
341	}
342	
343	impl LiveEcho {
344	    const NONE: Self = Self {
345	        stdout: false,
346	        stderr: false,
347	    };
348	    const STDERR: Self = Self {
349	        stdout: false,
350	        stderr: true,
351	    };
352	    /// A publish: pnpm prints its errors to stdout, so both streams are shown.
353	    const BOTH: Self = Self {
354	        stdout: true,
355	        stderr: true,
356	    };
357	}
358	
359	/// Drains `reader` to its end and returns what it said, keeping at most [`MAX_CAPTURED_OUTPUT_BYTES`]; the rest is
360	/// read and dropped so the child never blocks on a full pipe.
361	///
362	/// With `echo`, each line is also written to this process's stderr with `secrets` redacted first (registry tools can
363	/// echo a credential verbatim). The returned text stays raw so classifiers keep matching exact upstream text. Lines
364	/// are read as bytes: a line iterator has no bound on a single line, so a flood with no newlines would buffer without
365	/// limit before it could be capped.
366	fn capture_stream(mut reader: impl Read, echo: bool, secrets: &[String]) -> String {
367	    let mut captured: Vec<u8> = Vec::new();
368	    let mut truncated = false;
369	    let mut pending_line: Vec<u8> = Vec::new();
370	    let mut chunk = [0u8; 65536];
371	    let echo_line = |line: &mut Vec<u8>| {
372	        if line.last() == Some(&b'\r') {
373	            line.pop();
374	        }
375	        eprintln!("{}", redact_known_secrets(&String::from_utf8_lossy(line), secrets));
376	    };
377	    loop {
378	        match reader.read(&mut chunk) {
379	            Ok(0) | Err(_) => break,
380	            Ok(n) => {
381	                let data = &chunk[..n];
382	                if echo {
383	                    for &b in data {
384	                        if b == b'\n' {
385	                            echo_line(&mut pending_line);
386	                            pending_line.clear();
387	                        } else if pending_line.len() < MAX_CAPTURED_OUTPUT_BYTES {
388	                            pending_line.push(b);
389	                        }
390	                    }
391	                }
392	                if !truncated {
393	                    let take = data.len().min(MAX_CAPTURED_OUTPUT_BYTES - captured.len());
394	                    captured.extend_from_slice(&data[..take]);
395	                    truncated = take < data.len();
396	                }
397	            }
398	        }
399	    }
400	    if echo && !pending_line.is_empty() {
401	        echo_line(&mut pending_line);
402	    }
403	    let mut text = String::from_utf8_lossy(&captured).into_owned();
404	    if truncated {
405	        text.push_str("\n...[output truncated]\n");
406	    }
407	    text
408	}
409	
410	/// `live_secrets`: known-credential values (see
411	/// [`callisto_model::known_credential_env_values`]) to redact from each
412	/// line *before* it's echoed live to the terminal via `eprintln!`. This is
413	/// deliberately separate from -- and does not affect -- the `captured`
414	/// buffer that becomes the returned `CommandOutput.stderr`: that copy must
415	/// stay byte-for-byte raw so downstream classifiers (e.g.
416	/// `extract_retry_after_duration`, `detect_auth_failure`) can still match
417	/// exact upstream text. Callers pass the secrets list in rather than this
418	/// function reading the environment itself, keeping it pure and testable
419	/// with a synthetic list.
420	fn run_with_timeout_impl(
421	    program: &str,
422	    args: &[&str],
423	    cwd: &Path,
424	    timeout: Duration,
425	    echo: LiveEcho,
426	    live_secrets: Vec<String>,
427	    child_env: ChildEnvironment<'_>,
428	) -> Result<CommandOutput, CommandError> {
429	    let mut command = std::process::Command::new(program);
430	    command
431	        .args(args)
432	        .current_dir(cwd)
433	        .stdin(Stdio::null())
434	        .stdout(Stdio::piped())
435	        .stderr(Stdio::piped());
436	    for name in child_env.remove {
437	        command.env_remove(name);
438	    }
439	    for (name, value) in child_env.set {
440	        command.env(name, value);
441	    }
442	    let mut child = command.spawn().map_err(|e| {
443	        if e.kind() == std::io::ErrorKind::NotFound {
444	            CommandError::NotFound {
445	                program: program.to_string(),
446	            }
447	        } else {
448	            CommandError::Io {
449	                program: program.to_string(),
450	                message: e.to_string(),
451	            }
452	        }
453	    })?;
454	
455	    // Read stdout/stderr in separate threads to prevent pipe-buffer deadlock
456	    // when the child produces output while we wait for it to exit.
457	    let stdout_handle = child.stdout.take().expect("stdout was piped");
458	    let stderr_handle = child.stderr.take().expect("stderr was piped");
459	
460	    // The reader threads signal completion over a channel rather than
461	    // being joined directly. Killing (or the natural exit of) the
462	    // direct child does NOT close pipe fds held open by a descendant
463	    // process that inherited them (common for npm/cargo/python publish
464	    // lifecycle scripts spawning subprocesses). If that happens, the
465	    // blocking `read()` inside these threads never returns. Using
466	    // `recv_timeout` below lets us bound how long we wait for them
467	    // without ever blocking the caller indefinitely.
468	    let (stdout_tx, stdout_rx) = std::sync::mpsc::channel::<String>();
469	    let (stderr_tx, stderr_rx) = std::sync::mpsc::channel::<String>();
470	
471	    let stdout_secrets = live_secrets.clone();
472	    std::thread::spawn(move || {
473	        drop(stdout_tx.send(capture_stream(stdout_handle, echo.stdout, &stdout_secrets)));
474	    });
475	    // Stderr streams line by line so publish progress (cargo/npm/twine write to stderr) appears in real time rather
476	    // than after the process exits. `echo` gates only the live printing; captured output is identical either way.
477	    std::thread::spawn(move || {
478	        drop(stderr_tx.send(capture_stream(stderr_handle, echo.stderr, &live_secrets)));
479	    });
480

