257	    fn run_with_stdin(
258	        &self,
259	        program: &str,
260	        args: &[&str],
261	        cwd: &Path,
262	        stdin: &[u8],
263	    ) -> Result<CommandOutput, CommandError> {
264	        let mut command = std::process::Command::new(program);
265	        command.args(args).current_dir(cwd);
266	        remove_env(&mut command, &unrelated_credentials(program));
267	        let mut child = command
268	            .stdin(Stdio::piped())
269	            .stdout(Stdio::piped())
270	            .stderr(Stdio::piped())
271	            .spawn()
272	            .map_err(|e| {
273	                if e.kind() == std::io::ErrorKind::NotFound {
274	                    CommandError::NotFound {
275	                        program: program.to_string(),
276	                    }
277	                } else {
278	                    CommandError::Io {
279	                        program: program.to_string(),
280	                        message: e.to_string(),
281	                    }
282	                }
283	            })?;
284	
285	        // Write the payload on its own thread, concurrently with this
286	        // thread draining stdout/stderr via `wait_with_output` below.
287	        // A protocol like `git cat-file --batch` replies to each stdin
288	        // line as it arrives, so writing everything up front on the same
289	        // thread that also has to read the reply back could deadlock once
290	        // either the stdin or the stdout pipe buffer fills -- exactly the
291	        // hazard `run_with_timeout_impl` above uses dedicated reader
292	        // threads to avoid, mirrored here for the write side.
293	        let mut stdin_pipe = child.stdin.take().expect("stdin was requested as piped");
294	        let payload = stdin.to_vec();
295	        let writer = std::thread::spawn(move || {
296	            // A closed read end (the child exited early, e.g. on a bad
297	            // invocation) would otherwise surface as a `BrokenPipe` write
298	            // error here; the child's actual exit code/stderr, captured by
299	            // `wait_with_output` below, is the caller-facing signal for
300	            // that failure, so a write error on this thread is dropped
301	            // rather than reported.
302	            drop(stdin_pipe.write_all(&payload));
303	            drop(stdin_pipe.flush());
304	        });
305	
306	        let output = child.wait_with_output();
307	        // The writer thread only writes then drops its handle, so it must
308	        // already be finished (or about to finish) by the time the child
309	        // has exited and `wait_with_output` has drained its output --
310	        // joining here can't block indefinitely.
311	        drop(writer.join());
312	
313	        match output {
314	            Ok(o) => {
315	                let stderr = String::from_utf8_lossy(&o.stderr).into_owned();
316	                if !stderr.is_empty() {
317	                    let secrets = known_credential_env_values(std::env::vars());
318	                    eprint!("{}", redact_known_secrets(&stderr, &secrets));
319	                }
320	                note_failed_command(program, o.status.code(), &stderr);
321	                Ok(CommandOutput {
322	                    exit_code: o.status.code(),
323	                    stdout: String::from_utf8_lossy(&o.stdout).into_owned(),
324	                    stderr,
325	                })
326	            }
327	            Err(e) => Err(CommandError::Io {
328	                program: program.to_string(),
329	                message: e.to_string(),
330	            }),
331	        }
332	    }
333	}
