100	/// Redacts every occurrence of any non-empty string in `secrets` from
101	/// `text`, replacing each with `[REDACTED]`, then strips any URL userinfo
102	/// component (`REDACTED` -> `scheme://host`) regardless of
103	/// whether it matched a known secret.
104	///
105	/// Callers use this on raw subprocess stderr before it's embedded in a
106	/// [`RegistryError`] and, downstream, a JSON report or CI log — registry
107	/// CLIs (`cargo publish`, `npm publish`, `twine upload`) can echo a
108	/// credential verbatim in their own error diagnostics on auth failure.
109	///
110	/// Pure and injectable (`secrets` rather than reading the environment
111	/// directly) so it stays deterministic and test-friendly; see
112	/// [`known_credential_env_values`] for the real caller-side source of
113	/// `secrets`.
114	pub fn redact_known_secrets(text: &str, secrets: &[String]) -> String {
115	    let mut redacted = text.to_string();
116	    for secret in secrets {
117	        if !secret.is_empty() {
118	            redacted = redacted.replace(secret.as_str(), "[REDACTED]");
119	        }
120	    }
121	    redact_url_userinfo(&redact_token_shapes(&redacted))
122	}
123	
124	/// Token prefixes, the shortest run after each that counts as a token, so ordinary words are left alone.
125	const TOKEN_PREFIXES: &[(&str, usize)] = &[
126	    ("npm_", 20),
127	    ("ghp_", 20),
128	    ("gho_", 20),
129	    ("ghu_", 20),
130	    ("ghs_", 20),
131	    ("ghr_", 20),
132	    ("github_pat_", 20),
133	    ("pypi-", 20),
134	];
135	
136	fn is_token_char(c: char) -> bool {
137	    c.is_ascii_alphanumeric() || matches!(c, '_' | '-')
138	}
139	
140	/// Masks credentials that a registry tool echoes although none of them is in a known environment variable: tokens
141	/// with a well-known prefix, `Bearer` values and the value of an `.npmrc` `_authToken`, `_auth` or `_password` line.
142	fn redact_token_shapes(text: &str) -> String {
143	    let mut redacted = text.to_string();
144	    for (prefix, min_len) in TOKEN_PREFIXES {
145	        redacted = mask_after(
146	            &redacted,
147	            prefix,
148	            true,
149	            |value| value.chars().take_while(|c| is_token_char(*c)).count(),
150	            *min_len,
151	        );
152	    }
153	    redacted = mask_bearer(&redacted);
154	    for key in ["_authToken=", "_auth=", "_password="] {
155	        redacted = mask_after(
156	            &redacted,
157	            key,
158	            false,
159	            |value| {
160	                value
161	                    .find(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>'))
162	                    .unwrap_or(value.len())
163	            },
164	            1,
165	        );
166	    }
167	    redacted
168	}
