231	/// Filters an env-var snapshot down to registry-credential values this
232	/// codebase's publish flow reads: the names in [`SECRET_CREDENTIAL_ENV`], plus any
233	/// `CARGO_REGISTRIES_<NAME>_TOKEN` (operator-configured, unbounded name,
234	/// so matched by pattern). `GITHUB_TOKEN`/`GH_TOKEN` cover GitHub Actions'
235	/// ambient credential -- `redact_url_userinfo` already catches its most
236	/// realistic leak shape (an authenticated remote URL) independently, but
237	/// matching the env var names directly is cheap insurance against other
238	/// leak shapes.
239	///
240	/// Takes the snapshot as a parameter (callers pass `std::env::vars()`)
241	/// rather than reading the environment directly -- deterministic, no
242	/// process-env mutation in tests.
243	pub fn known_credential_env_values(vars: impl Iterator<Item = (String, String)>) -> Vec<String> {
244	    vars.filter(|(key, value)| {
245	        !value.is_empty()
246	            && (SECRET_CREDENTIAL_ENV.contains(&key.as_str())
247	                || (key.starts_with("CARGO_REGISTRIES_") && key.ends_with("_TOKEN"))
248	                || (value.len() >= MIN_SECRET_VALUE_LEN && SECRET_NAME_SUFFIXES.iter().any(|s| key.ends_with(s))))
249	    })
250	    .map(|(_, value)| value)
251	    .collect()
252	}
253	
254	/// Any variable named like a secret has its value redacted too, unless the value is so short that masking it would
255	/// mangle ordinary text.
256	const SECRET_NAME_SUFFIXES: &[&str] = &["_TOKEN", "_SECRET", "_PASSWORD"];
257	const MIN_SECRET_VALUE_LEN: usize = 8;
258	
259	/// The environment variables whose values are secrets. A username and the paths of generated config files
260	/// (`TWINE_USERNAME`, `NPM_CONFIG_USERCONFIG`, `CALLISTO_PUBLISH_NPM_CONFIG`) are credentials to keep out of
261	/// unrelated children but are not secret values, so they are not listed.
262	pub const SECRET_CREDENTIAL_ENV: &[&str] = &[
263	    "NPM_TOKEN",
264	    "NPM_CONFIG_TOKEN",
265	    "NODE_AUTH_TOKEN",
266	    "PYPI_TOKEN",
267	    "TWINE_PASSWORD",
268	    "CARGO_REGISTRY_TOKEN",
269	    "GITHUB_TOKEN",
270	    "GH_TOKEN",
271	];
272	
273	/// The one definition of "how this workspace redacts a subprocess's stderr":
274	/// [`redact_known_secrets`] over [`known_credential_env_values`] of the live
275	/// environment. Every path that puts child stderr in front of a human -- the
276	/// live echo, [`crate::CommandOutput::redacted_stderr`], and the
277	/// `CommandFailure::NonZeroExit` diagnostic -- composes it here rather than
278	/// repeating the composition, so none of them can drift out of step.
279	///
280	/// Reads the environment, so it is deliberately not the pure primitive;
281	/// unit tests target [`redact_known_secrets`] with an explicit secret list.
282	pub fn redact_command_stderr(stderr: &str) -> String {
283	    redact_known_secrets(stderr, &known_credential_env_values(std::env::vars()))
284	}
285	
286	/// Strips a URL's userinfo (`user:pass@` between `scheme://` and the
287	/// host) from every `scheme://...` occurrence in `text`, replacing it
288	/// with `[REDACTED]@`. Token-by-token: within the span from `scheme://`
289	/// to the next whitespace/quote/`<`/`>`, everything up to the *last* `@`
290	/// is treated as userinfo.
291	///
292	/// Deliberately conservative, not strictly RFC 3986-aware: userinfo with
293	/// a raw `/` or a second `@` (an unescaped base64-ish token) is realistic
294	/// in free-form CLI stderr, and using the *first* `@` would under-redact
295	/// exactly that case. Cost: a rare false positive (an `@` that's really
296	/// part of a path, e.g. an npm scoped package in
297	/// `registry.npmjs.org/@myorg/pkg`, gets redacted too) -- acceptable,
298	/// since over-redaction only costs log noise while under-redaction leaks
299	/// a credential.
300	fn redact_url_userinfo(text: &str) -> String {
301	    let mut result = String::with_capacity(text.len());
302	    let mut rest = text;
303	    while let Some(scheme_pos) = rest.find("://") {
304	        let split_at = scheme_pos + 3;
305	        result.push_str(&rest[..split_at]);
306	        let after = &rest[split_at..];
307	        let stop = after
308	            .find(|c: char| c.is_whitespace() || matches!(c, '"' | '\'' | '<' | '>'))
309	            .unwrap_or(after.len());
310	        let candidate = &after[..stop];
311	        if let Some(at_pos) = candidate.rfind('@') {
312	            result.push_str("[REDACTED]@");
313	            rest = &after[at_pos + 1..];
314	            continue;
315	        }
316	        rest = after;
317	    }
318	    result.push_str(rest);
319	    result
320	}
321	
322	#[cfg(test)]
323	mod tests {
324	    use super::*;
325	
326	    #[test]
327	    fn redacts_a_known_secret_value_from_text() {
328	        let text = "npm ERR! 403 Forbidden - PUT https://registry.npmjs.org/pkg - token abc123secret was rejected";
329	        let redacted = redact_known_secrets(text, &["abc123secret".to_string()]);
330	        assert!(!redacted.contains("abc123secret"));
331	        assert!(redacted.contains("[REDACTED]"));
332	    }
333	
334	    #[test]
335	    fn redacts_multiple_occurrences_of_the_same_secret() {
336	        let text = "token=s3cr3t failed; retrying with token=s3cr3t again";
337	        let redacted = redact_known_secrets(text, &["s3cr3t".to_string()]);
338	        assert!(!redacted.contains("s3cr3t"));
339	        assert_eq!(redacted.matches("[REDACTED]").count(), 2);
340	    }

